// @FIGURE_CODE_BEGIN
(function () {
  var C = {
    teal: '#0d7f8f', red: '#e8262d', blue: '#1a7fc1', accent: '#e07b1a',
    grid: '#c4c4c4', axis: '#111', gray: '#7f9aa0'
  };

  var state = { highlight: 'both', trace: 4.4, factor: 'factored' };
  function f(x) { return (x - 1) / (x - 3); }

  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  document.getElementById('container').appendChild(canvas);

  var ARROWS = [];
  var HIT = { hole: null, asym: null, trace: null };

  /* ---------- small drawing helpers ---------- */
  function sf(a) { return Math.max(0.5, Math.min(1.7, Math.min(a.width, a.height) / 480)); }
  function setFont(ctx, size, weight) {
    ctx.font = (weight ? weight + ' ' : '') + Math.max(7, size) + 'px Georgia, "Times New Roman", serif';
  }
  function txt(ctx, s, x, y, size, color, align, baseline, weight) {
    ctx.save();
    setFont(ctx, size, weight);
    ctx.textAlign = align || 'left';
    ctx.textBaseline = baseline || 'middle';
    ctx.lineJoin = 'round';
    ctx.lineWidth = Math.max(2, size * 0.30);
    ctx.strokeStyle = 'rgba(255,255,255,0.95)';
    ctx.strokeText(s, x, y);
    ctx.fillStyle = color;
    ctx.fillText(s, x, y);
    ctx.restore();
  }
  // parts = [{t:'...', c:'#color'}], right- or left-aligned line with white halo
  function txtParts(ctx, parts, x, y, size, align, weight) {
    ctx.save();
    setFont(ctx, size, weight);
    var total = 0, i;
    for (i = 0; i < parts.length; i++) total += ctx.measureText(parts[i].t).width;
    var cx = (align === 'right') ? x - total : x;
    ctx.textAlign = 'left';
