    data: {
      datasets: [
        { label: 'left', data: [], showLine: true, pointRadius: 0, borderColor: C.teal, borderWidth: 3, tension: 0, borderJoinStyle: 'round', borderCapStyle: 'round' },
        { label: 'right', data: [], showLine: true, pointRadius: 0, borderColor: C.teal, borderWidth: 3, tension: 0, borderJoinStyle: 'round', borderCapStyle: 'round' }
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      layout: { padding: 12 },
      events: [],
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      scales: {
        x: { type: 'linear', min: -4.6, max: 10.2, display: false, grid: { display: false } },
        y: { type: 'linear', min: -7.4, max: 7.4, display: false, grid: { display: false } }
      }
    },
    plugins: [figPlugin]
  });

  function buildData() {
    var xs = chart.options.scales.x, ys = chart.options.scales.y;
    var xMin = xs.min, xMax = xs.max, yMin = ys.min, yMax = ys.max;
    var xb = (1 - 3 * yMin) / (1 - yMin);   // left branch leaves through the bottom
    var xt = (1 - 3 * yMax) / (1 - yMax);   // right branch enters through the top
    var n = 420, L = [], R = [], i, t, x;
    for (i = 0; i <= n; i++) { t = i / n; x = xMin + (xb - xMin) * (1 - Math.pow(1 - t, 3)); L.push({ x: x, y: f(x) }); }
    for (i = 0; i <= n; i++) { t = i / n; x = xt + (xMax - xt) * Math.pow(t, 3); R.push({ x: x, y: f(x) }); }
    chart.data.datasets[0].data = L;
    chart.data.datasets[1].data = R;
    ARROWS = [
      { fx: xMin + 0.2, fy: f(xMin + 0.2), tx: xMin, ty: f(xMin) },
      { fx: xb - 0.04, fy: f(xb - 0.04), tx: xb, ty: yMin },
      { fx: xt + 0.04, fy: f(xt + 0.04), tx: xt, ty: yMax },
      { fx: xMax - 0.2, fy: f(xMax - 0.2), tx: xMax, ty: f(xMax) }
    ];
    var S = 1;
    if (chart.chartArea) S = sf(chart.chartArea);
    chart.data.datasets[0].borderWidth = 3 * S;
    chart.data.datasets[1].borderWidth = 3 * S;
  }

  function refit() {
    var w = canvas.clientWidth || 700, h = canvas.clientHeight || 460;
    var pad = 12;
    var aw = Math.max(60, w - 2 * pad), ah = Math.max(60, h - 2 * pad);
    var base = 14.8, xc = 2.8, xr, yr;
    if (aw >= ah) { yr = base; xr = base * aw / ah; } else { xr = base; yr = base * ah / aw; }
    var sc = chart.options.scales;
    sc.x.min = xc - xr / 2; sc.x.max = xc + xr / 2;
    sc.y.min = -yr / 2; sc.y.max = yr / 2;
    buildData();
    chart.resize();
    chart.update('none');
  }

  /* ---------- interactions ---------- */
  window.toggle_highlightBreak = function (v) { state.highlight = v; chart.update('none'); };
  window.toggle_factorView = function (v) { state.factor = v; chart.update('none'); };
  window.update_traceX = function (v) {
    state.trace = v;
    var y = f(v);
    document.getElementById('traceReadout').textContent =
      'f(' + v.toFixed(2) + ') = ' + fmt(y) + (Math.abs(v - 3) < 0.3 ? '   ← blowing up' : '');
    chart.update('none');
  };
  window.resetDemo = function () { goStep(0); };

  /* ---------- demo steps ---------- */
  var steps = [
    {
      t: 'The whole picture',
      n: 'The teal graph of f(x) = (x²−1)/((x+1)(x−3)) breaks in two places: a tiny hollow circle at x = −1 and a red dashed line at x = 3. Both are values where the denominator is zero, yet the graph behaves completely differently at each.',
      s: { highlight: 'both', factor: 'factored', trace: 4.4 }
    },
    {
      t: 'Zoom in on the hole',
      n: 'Highlighting only x = −1 shows a single point lifted out of an otherwise smooth curve. Points on either side sit at nearly the same height, about y = 0.5 — the graph does not run away anywhere.',
      s: { highlight: 'hole', factor: 'factored', trace: 4.4 }
    },
    {
      t: 'Why the hole is removable',
      n: 'Cancelling the common factor (x+1) leaves the simple function (x−1)/(x−3). The curve is unchanged, but now it is obvious that only one output value, f(−1) = 0.5, is missing.',
      s: { highlight: 'hole', factor: 'cancelled', trace: 4.4 }
    },
    {
      t: 'Approach the asymptote from the right',
      n: 'Now highlight x = 3 and slide the trace point down toward 3 from the right. The y-readout climbs past 10, 100, 1000 — the graph shoots upward with no limiting value.',
      s: { highlight: 'asym', factor: 'cancelled', trace: 3.06 }
    },
    {
      t: 'Approach from the left',
      n: 'Cross to the left side and the y-value plunges toward negative infinity instead. Because the two sides disagree and neither settles on a number, no single point can patch x = 3 — the factor (x−3) never cancels.',
      s: { highlight: 'asym', factor: 'cancelled', trace: 2.94 }
    }
  ];
  var cur = 0;

  function goStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    document.getElementById('stepTitle').textContent = st.t;
    document.getElementById('stepText').textContent = st.n;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    var hb = document.getElementById('highlightBreakInput');
    hb.value = st.s.highlight; window.toggle_highlightBreak(st.s.highlight);
    var fv = document.getElementById('factorViewInput');
    fv.value = st.s.factor; window.toggle_factorView(st.s.factor);
    var tr = document.getElementById('traceXInput');
    tr.value = st.s.trace;
    document.getElementById('traceXVal').value = (+st.s.trace).toFixed(2);
    window.update_traceX(+st.s.trace);
  }
  window.nextStep = function () { goStep(cur + 1); };
  window.prevStep = function () { goStep(cur - 1); };

  /* ---------- hover / click ---------- */
  function pick(mx, my) {
    var a = chart.chartArea; if (!a) return null;
    var S = sf(a);
    if (HIT.trace && Math.hypot(mx - HIT.trace[0], my - HIT.trace[1]) < 13 * S) return 'trace';
    if (HIT.hole && Math.hypot(mx - HIT.hole[0], my - HIT.hole[1]) < 14 * S) return 'hole';
    if (HIT.asym != null && Math.abs(mx - HIT.asym) < 8 * S && my > a.top && my < a.bottom) return 'asym';
    var xs = chart.scales.x, ys = chart.scales.y;
    var wx = xs.getValueForPixel(mx);
    if (Math.abs(wx - 3) > 0.12) {
      var py = ys.getPixelForValue(f(wx));
      if (Math.abs(py - my) < 9 * S) return 'curve';
    }
    return null;
  }
  var tips = {
    trace: function () { return 'Trace point: x = ' + state.trace.toFixed(2) + ',  f(x) = ' + fmt(f(state.trace)); },
    hole: function () { return 'Hole at x = \u22121: f(\u22121) is undefined, but nearby values crowd around 0.5'; },
    asym: function () { return 'Vertical asymptote x = 3: |f(x)| \u2192 \u221E as x \u2192 3'; },
    curve: function () { return 'f(x) = (x \u2212 1)/(x \u2212 3), the cancelled form of the rule'; }
  };
  var pops = {
    trace: ['Trace point', 'The dot rides the graph while the readout reports the exact output. Pushing x toward 3 makes |f(x)| grow past any bound you name, which is exactly what "no limit" looks like numerically.'],
    hole: ['Removable discontinuity at x = \u22121', 'Both numerator and denominator contain the factor (x + 1), so it cancels and the rule reduces to (x \u2212 1)/(x \u2212 3). Only the single output f(\u22121) = 0.5 is missing, so you could "fill the hole" by defining f(\u22121) = 0.5 and the graph would be continuous there.'],
    asym: ['Vertical asymptote at x = 3', 'The factor (x \u2212 3) survives in the denominator, so as x approaches 3 the quotient has a nonzero numerator over a vanishing denominator. The values run to \u2212\u221E from the left and +\u221E from the right, so no single value can repair the break.'],
    curve: ['The rational function', 'Away from x = \u22121 and x = 3 the function equals the simple quotient (x \u2212 1)/(x \u2212 3). It crosses the x-axis where the numerator is zero (x = 1) and flattens toward the horizontal asymptote y = 1 far from the origin.']
  };
  canvas.addEventListener('mousemove', function (e) {
    var r = canvas.getBoundingClientRect();
    var k = pick(e.clientX - r.left, e.clientY - r.top);
    if (k) { canvas.style.cursor = 'pointer'; showTooltip(tips[k](), e); }
    else { canvas.style.cursor = 'default'; hideTooltip(); }
  });
  canvas.addEventListener('mouseleave', function () { hideTooltip(); canvas.style.cursor = 'default'; });
  canvas.addEventListener('click', function (e) {
    var r = canvas.getBoundingClientRect();
    var k = pick(e.clientX - r.left, e.clientY - r.top);
    if (k) showPopup(pops[k][0], pops[k][1]);
  });

  /* ---------- boot ---------- */
  refit();
  goStep(0);
  window.__markRendered();

  var pending = 0;
  document.addEventListener('fig-resize', function () {
    cancelAnimationFrame(pending);
    pending = requestAnimationFrame(refit);
  });
})();
// @FIGURE_CODE_END

